pub(crate) fn py_is_space(c: char) -> bool {
    let cp = c as u32;
    PY_SPACE_RANGES.iter().any(|&(a, b)| cp >= a && cp <= b)
}

pub(crate) fn py_is_printable(c: char) -> bool {
    let cp = c as u32;
    PY_PRINTABLE_RANGES.iter().any(|&(a, b)| cp >= a && cp <= b)
}
