/// repeated here only so this file compiles and is tested on its own.
pub const OLE2_MAGIC: [u8; 8] = [0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1];

/// The `50 * 1024 * 1024` ceiling checked by both `doc2md` (:1181) and
/// `_doc_extract_text_pure_python` (:1068).
pub const DOC_MAX_BYTES: u64 = 50 * 1024 * 1024;

/// `max_total_chars = 10_000_000` (:1098).
const CLX_MAX_TOTAL_CHARS: usize = 10_000_000;

/// `range(min(n_pcd, 50000))` (:1117).
const CLX_MAX_PIECES: usize = 50_000;

/// The literal prefix tuple at :1021, in source order.
const STREAM_NOISE_PREFIXES: [&str; 6] = [
    "Root Entry",
    "WordDocument",
    "SummaryInformation",
    "DocumentSummaryInformation",
    "CompObj",
    "Normal.dot",
];

/// Code points that `str.endswith(('。','！','？','.','!','?','；',';','，',','))`
/// tests at :868.
const SENTENCE_TERMINATORS: [char; 10] = [
    '\u{3002}', '\u{ff01}', '\u{ff1f}', '.', '!', '?', '\u{ff1b}', ';', '\u{ff0c}', ',',
];

// ////////////////////////////////////////////////////////////////////////////////
// Cross-module seams
// ////////////////////////////////////////////////////////////////////////////////

/// Everything this module needs from another lane's file.
///
/// ```text
// WIRING: `extract_ole2_streams`  -> `crate::ole2::extract_ole2_streams(data,
// WIRING:                           &["WordDocument", "0Table", "1Table"])`, then
// WIRING:                           `.entries`.  Order must be *directory* order,
// WIRING:                           not `wanted` order, and a repeated name must
// WIRING:                           keep its first position (Python dict rules).
// WIRING: `decode_utf16le_ignore` -> `crate::ole2::decode_utf16le_ignore`
// WIRING: `decode_utf16le_replace`-> `crate::ole2::decode_utf16le_replace`
// WIRING: `decode_gb18030_strict` -> `crate::codecs::try_decode_strict(raw, "gb18030")`,
// WIRING:                           mapping an error to `None`.  This is the only
// WIRING:                           rung of the decode ladder this file cannot own:
// WIRING:                           the full GB18030 table belongs to `codecs.rs`.
// WIRING: `cp1252_strict` / `cp1252_replace` / `latin1_decode` / `utf8_strict` are
// WIRING:   reimplemented privately below from a measured 256-entry table so that
// WIRING:   the ladder, and therefore `decode_doc_ansi_bytes`, is testable here.
// WIRING:   At integration time these can be dropped in favour of `codecs.rs`.
/// ```
pub trait DocKernel {
    /// `convert._extract_ole2_streams(data, wanted_names)` -> its dict, as pairs.
    fn extract_ole2_streams(&self, data: &[u8], wanted: &[&str]) -> Vec<(String, Vec<u8>)>;
    /// `raw.decode('gb18030')`, strict.  `None` models `UnicodeDecodeError`.
    fn decode_gb18030_strict(&self, raw: &[u8]) -> Option<String>;
    /// `raw.decode('utf-16le', errors='replace')`
    fn decode_utf16le_replace(&self, raw: &[u8]) -> String;
    /// `raw.decode('utf-16le', errors='ignore')`
    fn decode_utf16le_ignore(&self, raw: &[u8]) -> String;
}

/// The `str` / `bytes` overload of `_parse_doc_stream_to_md`'s single argument.
/// Which variant it is changes the output -- see fidelity note 1.
#[derive(Debug, Clone, Copy)]
pub enum DocStream<'a> {
    /// `isinstance(stream_data, str)`: text is used as-is, ratio gate skipped.
    Text(&'a str),
    /// Raw bytes: UTF-16LE sniff plus the `utf-8/gb18030/cp1252/latin1` ladder,
    /// and the printable-ratio gate applies.
    Bytes(&'a [u8]),
}

// ////////////////////////////////////////////////////////////////////////////////
// CPython-shaped primitives
// ////////////////////////////////////////////////////////////////////////////////

/// `str.strip()` with no argument: strips every code point for which CPython's
/// `str.isspace()` is true, i.e. Rust's `char::is_whitespace()` **plus**
/// U+001C..U+001F.
pub fn py_strip(s: &str) -> &str {
    let trimmed_start = s
        .char_indices()
        .find(|(_, c)| !py_is_space(*c))
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    let head = &s[trimmed_start..];
    let mut trimmed_end = head.len();
    for (i, c) in head.char_indices().rev() {
        if py_is_space(c) {
            trimmed_end = i;
        } else {
            break;
        }
    }
    &head[..trimmed_end]
}

/// `str.lstrip()`
#[allow(dead_code)]
pub fn py_strip_start(s: &str) -> &str {
    let i = s
        .char_indices()
        .find(|(_, c)| !py_is_space(*c))
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    &s[i..]
}

/// `len(str)` -- code points, not bytes.
pub fn py_len(s: &str) -> usize {
    s.chars().count()
}

/// `str.endswith(tuple_of_chars)`
fn py_ends_with_any(s: &str, chars: &[char]) -> bool {
    match s.chars().next_back() {
        Some(last) => chars.contains(&last),
        None => false,
    }
}

/// `bytes.count(b'\x00')`
fn count_byte(hay: &[u8], needle: u8) -> usize {
    hay.iter().filter(|&&b| b == needle).count()
}

/// `sub in bytes`
fn contains_sub(hay: &[u8], sub: &[u8]) -> bool {
    !sub.is_empty() && hay.windows(sub.len()).any(|w| w == sub)
}

/// `struct.unpack_from('<H', d, at)`; `None` models the `struct.error` that the
/// blanket `except Exception` at :1170 turns into `''`.
fn u16_at(d: &[u8], at: usize) -> Option<u16> {
    if at.checked_add(2)? > d.len() {
        return None;
    }
    Some(u16::from_le_bytes([d[at], d[at + 1]]))
}

/// `struct.unpack_from('<I', d, at)`
fn u32_at(d: &[u8], at: usize) -> Option<u32> {
    if at.checked_add(4)? > d.len() {
        return None;
    }
    Some(u32::from_le_bytes([d[at], d[at + 1], d[at + 2], d[at + 3]]))
}

/// `bytes.decode('latin1')` -- total, never raises, so it terminates the ladder.
fn latin1_decode(raw: &[u8]) -> String {
    raw.iter()
        .map(|&b| <char as std::convert::TryFrom<u32>>::try_from(u32::from(b))
            .unwrap_or('\u{fffd}'))
        .collect()
}

/// `bytes.decode('utf-8')` -- strict.
fn utf8_strict(raw: &[u8]) -> Option<String> {
    std::str::from_utf8(raw).ok().map(str::to_string)
}

/// `bytes.decode('cp1252')` -- strict; the undefined slots raise.
fn cp1252_strict(raw: &[u8]) -> Option<String> {
    let mut out = String::with_capacity(raw.len());
    for &b in raw {
        out.push(CP1252[usize::from(b)]?);
    }
    Some(out)
}

/// `bytes.decode('cp1252', errors='replace')` -- one U+FFFD per bad byte.
fn cp1252_replace(raw: &[u8]) -> String {
    raw.iter()
        .map(|&b| CP1252[usize::from(b)].unwrap_or('\u{fffd}'))
        .collect()
}

// ////////////////////////////////////////////////////////////////////////////////
// `_classify_doc_heading` -- convert.py:849
// ////////////////////////////////////////////////////////////////////////////////

/// `re.match(r'^[\u2022\u00b7\*\-]\s+', line)` -- `\s` is CPython's, so U+001C..U+001F
/// and U+00A0 also satisfy the `+`.
fn starts_bullet(s: &str) -> bool {
    let mut it = s.chars();
    match it.next() {
        Some(c) if is_bullet_char(c) => matches!(it.next(), Some(c) if py_is_space(c)),
        _ => false,
    }
}

/// The `[\u2022\u00b7\*\-]` class; `\-` is a literal hyphen.
fn is_bullet_char(c: char) -> bool {
    matches!(c, '\u{2022}' | '\u{00b7}' | '*' | '-')
}

/// `[\.\s、]` -- dot, CPython whitespace, or the ideographic comma U+3001.
fn is_dot_ws_dun(c: char) -> bool {
    c == '.' || c == '\u{3001}' || py_is_space(c)
}

fn is_ascii_digit_c(c: char) -> bool {
    c.is_ascii_digit()
}

const CN_DIGITS: &str = "一二三四五六七八九";
/// `第[一二三四五六七八九十百0-9]+` (level 1) -- note `百` only in the level-1 class.
fn in_cn_num_l1(c: char) -> bool {
    CN_DIGITS.contains(c) || c == '十' || c == '百' || c.is_ascii_digit()
}
/// `第[一二三四五六七八九十0-9]+` (level 2) -- no `百`.
fn in_cn_num_l2(c: char) -> bool {
    CN_DIGITS.contains(c) || c == '十' || c.is_ascii_digit()
}
/// `[一二三四五六七八九十]`, for the parenthesised level-2 forms.
fn in_cn_ten(c: char) -> bool {
    CN_DIGITS.contains(c) || c == '十'
}

const HEAD_ENDS_L1: [char; 4] = ['章', '篇', '部', '卷'];
const HEAD_ENDS_L2: [char; 2] = ['节', '条'];

fn is_cjk_or_latin(c: char) -> bool {
    ('\u{4e00}'..='\u{9fa5}').contains(&c) || c.is_ascii_alphabetic()
}

/// `[0-9]{1,2}` immediately followed by a character satisfying `next`.
/// Returns the number of code points consumed *including* the delimiter, or
/// `None`.  Tries 2 digits first, matching the greedy quantifier; `re.match`
/// only reports success or failure here, so existence is what matters.
fn match_num12<P: Fn(char) -> bool>(cs: &[char], at: usize, next: P) -> Option<usize> {
    let n = cs.len();
    for k in [2usize, 1] {
        if at + k > n {
            continue;
        }
        if !cs[at..at + k].iter().all(|c| is_ascii_digit_c(*c)) {
            continue;
        }
        if at + k < n && next(cs[at + k]) {
            return Some(k + 1);
        }
    }
    None
}

/// `[0-9]+` followed by a character satisfying `next`.
fn match_digits_then<P: Fn(char) -> bool>(cs: &[char], at: usize, next: P) -> bool {
    let n = cs.len();
    let mut i = at;
    while i < n && cs[i].is_ascii_digit() {
        i += 1;
    }
    i > at && i < n && next(cs[i])
}

/// `第<cn-class><ends>`: returns true when `cs[0] == '第'` and a non-empty run of
/// `cls` is followed by one of `ends`.
fn match_dai<P: Fn(char) -> bool, Q: Fn(char) -> bool>(
    cs: &[char],
    cls: P,
    ends: Q,
) -> bool {
    let n = cs.len();
    if n < 3 || cs[0] != '第' {
        return false;
    }
    let mut i = 1;
    while i < n && cls(cs[i]) {
        i += 1;
    }
    i > 1 && i < n && ends(cs[i])
}

/// `convert._classify_doc_heading(line)` -> `Some(1|2|3)` or `None`.
///
/// The *order* of the three groups is load-bearing: level 3 is tested before
/// level 2, so `1.1.1 x` wins as an h3 even though it also begins with an h2
/// shape, while `1.1` falls through to level 2.
pub fn classify_doc_heading(line: &str) -> Option<usize> {
    let line = py_strip(line);
    if line.is_empty() || py_len(line) > 60 {
        return None;
    }
    if starts_bullet(line) {
        return None;
    }
    let cs: Vec<char> = line.chars().collect();
    let n = cs.len();

    // 1 级标题：第X章/篇/卷、一、大写数字序号
    if match_dai(&cs, in_cn_num_l1, |c| HEAD_ENDS_L1.contains(&c)) {
        return Some(1);
    }
    if n >= 2 && cs[0] == '一' && is_dot_ws_dun(cs[1]) {
        return Some(1);
    }
    if let Some(adv) = match_num12(&cs, 0, is_dot_ws_dun) {
        let mut j = adv;
        while j < n && py_is_space(cs[j]) {
            j += 1;
        }
        if j < n && is_cjk_or_latin(cs[j]) {
            return Some(1);
        }
    }

    // 3 级标题：1.1.1、(1)、1)
    if let Some(a) = match_num12(&cs, 0, |c| c == '.') {
        if let Some(b) = match_num12(&cs, a, |c| c == '.') {
            if match_num12(&cs, b, is_dot_ws_dun).is_some() {
                return Some(3);
            }
        }
    }
    if n >= 3 && cs[0] == '\u{ff08}' && match_digits_then(&cs, 1, |c| c == '\u{ff09}') {
        return Some(3);
    }
    if n >= 3 && cs[0] == '(' && match_digits_then(&cs, 1, |c| c == ')') {
        return Some(3);
    }
    if match_num12(&cs, 0, |c| c == ')').is_some() {
        return Some(3);
    }

    // 2 级标题：第X节/条、1.1、(一)
    if match_dai(&cs, in_cn_num_l2, |c| HEAD_ENDS_L2.contains(&c)) {
        return Some(2);
    }
    if let Some(a) = match_num12(&cs, 0, |c| c == '.') {
        if match_num12(&cs, a, is_dot_ws_dun).is_some() {
            return Some(2);
        }
    }
    for (open, close) in [('\u{ff08}', '\u{ff09}'), ('(', ')')] {
        if n >= 3 && cs[0] == open {
            let mut i = 1;
            while i < n && in_cn_ten(cs[i]) {
                i += 1;
            }
            if i > 1 && i < n && cs[i] == close {
                return Some(2);
            }
        }
    }

    // 独立短行（<=30字符且无句尾终止标点）
    if py_len(line) <= 30 && !py_ends_with_any(line, &SENTENCE_TERMINATORS) {
        return Some(2);
    }
    None
}

/// `re.sub(r'^[#\s]+', '', s)` -- greedy, so it stops at the first non-`#`,
/// non-whitespace code point.
fn strip_leading_hash_ws(s: &str) -> String {
    let keep = s
        .char_indices()
        .find(|(_, c)| *c != '#' && !py_is_space(*c))
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    s[keep..].to_string()
}

/// `re.sub(r'^[\u2022\u00b7\*\-]\s*', '', s)` -- note `\s*`, not `\s+`: with no
/// bullet character the pattern matches nothing and the text is returned as-is.
fn strip_bullet_marker(s: &str) -> String {
    let mut it = s.char_indices();
    match it.next() {
        Some((_, c)) if is_bullet_char(c) => {}
        _ => return s.to_string(),
    }
    let keep = it
        .find(|(_, c)| !py_is_space(*c))
        .map(|(i, _)| i)
        .unwrap_or(s.len());
    s[keep..].to_string()
}

/// `re.sub(r'[ \t]+', ' ', s)` -- deliberately **not** `\s+`: only SPACE and TAB
/// collapse, so U+00A0 / U+3000 inside a cell survive (fidelity note 9).
fn squash_space_tab(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut in_run = false;
    for c in s.chars() {
        if c == ' ' || c == '\t' {
            if !in_run {
                out.push(' ');
                in_run = true;
            }
        } else {
            out.push(c);
            in_run = false;
        }
    }
    out
}

/// `re.match(r'^[0-9]+[\.\s、]\s*', line_clean)` -- the dead branch's test.
fn matches_ordered_number(s: &str) -> bool {
    let cs: Vec<char> = s.chars().collect();
    match_digits_then(&cs, 0, is_dot_ws_dun)
}

// ////////////////////////////////////////////////////////////////////////////////
// `_parse_doc_stream_to_md` -- convert.py:944
// ////////////////////////////////////////////////////////////////////////////////

/// `'| ' + ' | '.join(row + [''] * (max_cols - len(row))) + ' |'`
fn render_md_row(row: &[String], max_cols: usize) -> String {
    let mut cells: Vec<&str> = row.iter().map(String::as_str).collect();
    while cells.len() < max_cols {
        cells.push("");
    }
    format!("| {} |", cells.join(" | "))
}

/// The nested `flush_table()` (:988).  Rows arrive already stripped and
/// pipe-escaped; `strip()` at :994 runs a second time, exactly as in Python.
fn flush_table(current: &mut Vec<Vec<String>>, blocks: &mut Vec<String>) {
    if current.is_empty() {
        return;
    }
    let valid_rows: Vec<Vec<String>> = current
        .iter()
        .map(|r| {
            r.iter()
                .map(|c| py_strip(c).to_string())
                .collect::<Vec<_>>()
        })
        .filter(|cells: &Vec<String>| cells.iter().any(|c| !c.is_empty()))
        .collect();
    current.clear();
    if valid_rows.is_empty() {
        return;
    }

    let max_cols = valid_rows.iter().map(|r| r.len()).max().unwrap_or(0);
    if max_cols >= 2 {
        let mut tbl_lines = Vec::with_capacity(valid_rows.len() + 1);
        tbl_lines.push(render_md_row(&valid_rows[0], max_cols));
        let sep: Vec<&str> = vec!["---"; max_cols];
        tbl_lines.push(format!("| {} |", sep.join(" | ")));
        for r in valid_rows.iter().skip(1) {
            tbl_lines.push(render_md_row(r, max_cols));
        }
        blocks.push(tbl_lines.join("\n"));
    } else {
        for r in &valid_rows {
            blocks.push(r.join(" "));
        }
    }
}

/// `convert._parse_doc_stream_to_md(stream_data)`
pub fn parse_doc_stream_to_md(kernel: &dyn DocKernel, stream_data: DocStream<'_>) -> String {
    // ---- text acquisition (:948-960) ------------------------------------------
    let text: String = match stream_data {
        DocStream::Text(s) => s.to_string(),
        DocStream::Bytes(b) => {
            if contains_sub(b, b"\x07\x00") || count_byte(b, 0) > b.len() / 4 {
                kernel.decode_utf16le_ignore(b)
            } else {
                // for enc in ('utf-8', 'gb18030', 'cp1252', 'latin1')
                utf8_strict(b)
                    .or_else(|| kernel.decode_gb18030_strict(b))
                    .or_else(|| cp1252_strict(b))
                    .unwrap_or_else(|| latin1_decode(b))
            }
        }
    };

    // ---- gates (:962-971) -----------------------------------------------------
    if text.is_empty() || py_len(py_strip(&text)) < 4 {
        return String::new();
    }
    let valid_chars = text
        .chars()
        .filter(|&ch| py_is_printable(ch) || matches!(ch, '\t' | '\r' | '\n' | '\u{7}'))
        .count();
    if valid_chars < 4 {
        return String::new();
    }
    // `if not isinstance(stream_data, str)` -- bytes only.
    if matches!(stream_data, DocStream::Bytes(_)) {
        if (valid_chars as f64) / (py_len(&text).max(1) as f64) < 0.35_f64 {
            return String::new();
        }
    }

    // ---- control-character clean (:974-982) ----------------------------------
    let cleaned: String = text
        .chars()
        .map(|ch| {
            if matches!(ch, '\u{7}' | '\t' | '\r' | '\n') || (ch as u32) >= 32 {
                ch
            } else {
                ' '
            }
        })
        .collect();
    let cleaned = cleaned.replace("\r\n", "\n").replace('\r', "\n");

    // ---- line walk (:1015-1053) ----------------------------------------------
    let mut md_blocks: Vec<String> = Vec::new();
    let mut current_table: Vec<Vec<String>> = Vec::new();

    for line in cleaned.split('\n') {
        let line_clean = py_strip(line);
        if line_clean.is_empty() {
            flush_table(&mut current_table, &mut md_blocks);
            continue;
        }
        // No flush_table() before this `continue` -- see fidelity note 7.
        if STREAM_NOISE_PREFIXES
            .iter()
            .any(|p| line_clean.starts_with(p))
        {
            continue;
        }
        // `if '\x07' in line:` -- the *raw* line, not `line_clean`.
        if line.contains('\u{7}') {
            let mut cells: Vec<String> = line
                .split('\u{7}')
                .map(|p| squash_space_tab(&py_strip(p).replace('|', "\\|")))
                .collect();
            if cells.len() > 1 && cells.last().map_or(false, |c| c.is_empty()) {
                cells.pop();
            }
            if cells.iter().any(|c| !c.is_empty()) {
                current_table.push(cells);
            }
            continue;
        }
        flush_table(&mut current_table, &mut md_blocks);

        if starts_bullet(line_clean) {
            md_blocks.push(format!("- {}", strip_bullet_marker(line_clean)));
            continue;
        }
        if let Some(lvl) = classify_doc_heading(line_clean) {
            md_blocks.push(format!(
                "{} {}",
                "#".repeat(lvl),
                strip_leading_hash_ws(line_clean)
            ));
        } else if matches_ordered_number(line_clean) {
            // Dead branch in the authority: identical to the `else`.
            md_blocks.push(line_clean.to_string());
        } else {
            md_blocks.push(line_clean.to_string());
        }
    }
    flush_table(&mut current_table, &mut md_blocks);
    md_blocks.join("\n\n")
}

// ////////////////////////////////////////////////////////////////////////////////
// `_decode_doc_ansi_bytes` -- convert.py:1057
// ////////////////////////////////////////////////////////////////////////////////

/// `convert._decode_doc_ansi_bytes(raw_bytes)`
pub fn decode_doc_ansi_bytes(kernel: &dyn DocKernel, raw_bytes: &[u8]) -> String {
    match kernel.decode_gb18030_strict(raw_bytes) {
        Some(s) => s,
        None => cp1252_replace(raw_bytes),
    }
}

// ////////////////////////////////////////////////////////////////////////////////
// `_doc_extract_text_pure_python` -- convert.py:1065
// ////////////////////////////////////////////////////////////////////////////////

/// `convert._doc_extract_text_pure_python(path)`
pub fn doc_extract_text_pure_python(kernel: &dyn DocKernel, path: &Path) -> String {
    // `os.path.getsize` (:1068) and `open(path,'rb')` (:1070) are both inside the
    // blanket `except Exception: pass` (:1170), so an unreadable file yields ''
    // exactly like a malformed one.
    match std::fs::metadata(path) {
        Ok(m) if m.len() > DOC_MAX_BYTES => return String::new(),
        Ok(_) => {}
        Err(_) => return String::new(),
    }
    match std::fs::read(path) {
        Ok(d) => doc_extract_text_pure_python_from_data(kernel, &d),
        Err(_) => String::new(),
    }
}

/// The body of `_doc_extract_text_pure_python` once `data` is in memory, so the
/// FIB / CLX tiers can be tested without a filesystem.
pub fn doc_extract_text_pure_python_from_data(kernel: &dyn DocKernel, data: &[u8]) -> String {
    pure_inner(kernel, data).unwrap_or_default()
}

/// `Err(())` stands in for "an exception escaped"; the Python
/// `except Exception: pass` (:1170) renders that as `''`.
fn pure_inner(kernel: &dyn DocKernel, data: &[u8]) -> Result<String, ()> {
    if data.is_empty() || data.len() < 512 || data[..8] != OLE2_MAGIC {
        return Ok(String::new());
    }

    let streams =
        kernel.extract_ole2_streams(data, &["WordDocument", "0Table", "1Table"]);
    let find = |name: &str| -> Option<&[u8]> {
        streams
            .iter()
            .find(|(k, _)| k == name)
            .map(|(_, v)| v.as_slice())
    };
    let word_doc = match find("WordDocument") {
        Some(b) if !b.is_empty() => b,
        // `if not word_doc: return ''` -- covers both absent and empty.
        _ => return Ok(String::new()),
    };

    // 1. FIB (File Information Block) + Piece Table / CLX
    if word_doc.len() >= 80 {
        let w_ident = u16_at(word_doc, 0).ok_or(())?;
        if w_ident == 0xA5EC {
            let flags = u16_at(word_doc, 10).ok_or(())?;
            let f_which_tbl_stm = flags & 0x0200 != 0;
            let tbl_name = if f_which_tbl_stm { "1Table" } else { "0Table" };
            let tbl_stream = find(tbl_name);

            // 1.1 CLX / piece table -- the "complex or fast-saved" format.
            if let Some(tbl) = tbl_stream.filter(|t| !t.is_empty()) {
                if word_doc.len() >= 426 {
                    let fc_clx = u64::from(u32_at(word_doc, 418).ok_or(())?);
                    let lcb_clx = u64::from(u32_at(word_doc, 422).ok_or(())?);
                    if fc_clx + lcb_clx <= tbl.len() as u64 && lcb_clx > 0 {
                        let from = fc_clx as usize;
                        let to = from + lcb_clx as usize;
                        let clx: &[u8] = &tbl[from..to];
                        let pieces_text = walk_clx(kernel, clx, word_doc)?;
                        if !pieces_text.is_empty() {
                            let full_str = pieces_text.join("");
                            let md = parse_doc_stream_to_md(
                                kernel,
                                DocStream::Text(&full_str),
                            );
                            if !md.is_empty() && !py_strip(&md).is_empty() {
                                return Ok(py_strip(&md).to_string());
                            }
                        }
                    }
                }
            }

            // 1.2 fcMin / ccpText slice, to shed the FIB and the trailing styles.
            let fc_min = usize::try_from(u32_at(word_doc, 24).ok_or(())?).unwrap_or(usize::MAX);
            let ccp_text = u32_at(word_doc, 76).ok_or(())?;
            if fc_min > 0 && fc_min < word_doc.len() && ccp_text > 0 {
                for scale in [2usize, 1usize] {
                    let max_chars = (word_doc.len() - fc_min) / scale;
                    let ccp = std::cmp::min(ccp_text as usize, max_chars);
                    if ccp == 0 {
                        continue;
                    }
                    let to = fc_min + ccp * scale;
                    if to > word_doc.len() {
                        return Err(());
                    }
                    let slice = &word_doc[fc_min..to];
                    let slice_str = if scale == 2 {
                        kernel.decode_utf16le_replace(slice)
                    } else {
                        decode_doc_ansi_bytes(kernel, slice)
                    };
                    let md = parse_doc_stream_to_md(kernel, DocStream::Text(&slice_str));
                    if !md.is_empty() && !py_strip(&md).is_empty() {
                        return Ok(py_strip(&md).to_string());
                    }
                }
            }
        }
    }

    // 2. 兜底：whole stream, as *bytes* -- so the ratio gate applies here and only here.
    let md = parse_doc_stream_to_md(kernel, DocStream::Bytes(word_doc));
    if !md.is_empty() && !py_strip(&md).is_empty() {
        return Ok(py_strip(&md).to_string());
    }
    Ok(String::new())
}

/// The `while pos < len(clx)` loop at :1099, returning `pieces_text`.
fn walk_clx(kernel: &dyn DocKernel, clx: &[u8], word_doc: &[u8]) -> Result<Vec<String>, ()> {
    let mut pos = 0usize;
    let mut pieces_text: Vec<String> = Vec::new();
    let mut total_chars = 0usize;

    while pos < clx.len() && total_chars < CLX_MAX_TOTAL_CHARS {
        match clx[pos] {
            // clxt == 1: a Grpprl, skip `3 + cbGrpprl`.
            1 => {
                if pos + 3 > clx.len() {
                    break;
                }
                let cb_grpprl = u16_at(clx, pos + 1).ok_or(())? as usize;
                pos = pos + 3 + cb_grpprl;
            }
            // clxt == 2: the Pcdt.
            2 => {
                if pos + 5 > clx.len() {
                    break;
                }
                let lcb = usize::try_from(u32_at(clx, pos + 1).ok_or(())?).unwrap_or(usize::MAX);
                pos += 5;
                // `clx[pos:pos + lcb]` is a *lenient* Python slice.
                let to = pos.saturating_add(lcb).min(clx.len());
                let pcdt_data: &[u8] = &clx[pos.min(clx.len())..to];
                if pcdt_data.len() >= 4 {
                    // `(lcb - 4) // (4 + 8)` with Python's floor division, which
                    // for lcb < 4 is *negative* and therefore fails `n_pcd > 0`.
                    let n_pcd: i64 = (i64::try_from(lcb).unwrap_or(i64::MAX) - 4) / 12;
                    if n_pcd > 0 {
                        let n_pcd = n_pcd as usize;
                        let need = (n_pcd + 1) * 4 + n_pcd * 8;
                        if pcdt_data.len() >= need {
                            let mut cps: Vec<u32> = Vec::with_capacity(n_pcd + 1);
                            for i in 0..=n_pcd {
                                cps.push(u32_at(pcdt_data, i * 4).ok_or(())?);
                            }
                            let pcds_offset = (n_pcd + 1) * 4;
                            let lim = n_pcd.min(CLX_MAX_PIECES);
                            for idx in 0..lim {
                                let cp_start = cps[idx];
                                let cp_end = cps[idx + 1];
                                if cp_end <= cp_start {
                                    continue;
                                }
                                let char_count = (cp_end - cp_start) as usize;
                                let char_count = char_count.min(CLX_MAX_TOTAL_CHARS - total_chars);
                                if char_count == 0 {
                                    break;
                                }
                                let a = pcds_offset + idx * 8;
                                let pcd = &pcdt_data[a..a + 8];
                                let fc_val = u32_at(pcd, 2).ok_or(())?;
                                let f_compressed = fc_val & 0x4000_0000 != 0;
                                let fc = fc_val & !0x4000_0000;
                                let actual_offset =
                                    usize::try_from(if f_compressed { fc / 2 } else { fc })
                                        .unwrap_or(usize::MAX);
                                if actual_offset >= word_doc.len() {
                                    continue;
                                }
                                let avail = word_doc.len() - actual_offset;
                                let want = if f_compressed {
                                    char_count
                                } else {
                                    char_count.saturating_mul(2)
                                };
                                let take = want.min(avail);
                                let raw_bytes = &word_doc[actual_offset..actual_offset + take];
                                let piece_str = if f_compressed {
                                    decode_doc_ansi_bytes(kernel, raw_bytes)
                                } else {
                                    kernel.decode_utf16le_replace(raw_bytes)
                                };
                                // `total_chars += len(piece_str)` -- code points.
                                total_chars += py_len(&piece_str);
                                pieces_text.push(piece_str);
                            }
                        }
                    }
                }
                break;
            }
            _ => break,
        }
    }
    Ok(pieces_text)
}

