/// A `.docx` path as Python would have it: the converters return whatever string
/// they built, and `os.path.isfile()` is applied to it directly, so an empty or
/// non-existent value must simply fail the `if out and isfile(out)` test at :1197.
pub type ConvertedDocx = String;

/// `doc2md`'s `(text, error)` pair.  `error == None` means success.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DocMdResult {
    pub text: String,
    pub error: Option<String>,
}

impl DocMdResult {
    pub fn ok(text: impl Into<String>) -> Self {
        DocMdResult { text: text.into(), error: None }
    }
    pub fn err(error: impl Into<String>) -> Self {
        DocMdResult { text: String::new(), error: Some(error.into()) }
    }
}

/// The two external conversion engines and the `.docx` reader they feed.
/// `_doc2docx_word_com` (convert.py:762) drives Word through COM,
/// `_doc2docx_soffice` (:836) drives LibreOffice as a subprocess, and `docx2md`
/// (:1731) is the OOXML reader; all three belong to `convert.rs`.
///
/// ```text
// WIRING: `doc2docx_word_com(src, out_dir)` -> `crate::convert::_doc2docx_word_com`
//   with `timeout=30`.  It must surface a raised exception as `Err(msg)` where
//   `msg == str(e)`, because :1206 interpolates it into
//   `doc-convert-failed：转换引擎执行失败（%s）` verbatim.
// WIRING: `doc2docx_soffice(src, out_dir)`  -> `crate::convert::_doc2docx_soffice`
// WIRING: `docx2md(out, form_tables, asset_source)` -> `crate::convert::docx2md`.
//   Its `(text, error)` tuple is returned from `doc2md` **unchanged**, error
//   included: at :1198 the authority does not inspect the second element, so a
//   `.doc` whose `.docx` conversion itself failed still reports success.
/// ```
pub trait DocEngines {
    fn doc2docx_word_com(
        &self,
        src: &Path,
        out_dir: &Path,
    ) -> Result<Option<ConvertedDocx>, String>;
    fn doc2docx_soffice(
        &self,
        src: &Path,
        out_dir: &Path,
    ) -> Result<Option<ConvertedDocx>, String>;
    fn docx2md(&self, docx: &Path, form_tables: bool, asset_source: &Path) -> DocMdResult;
}

