/// `tempfile.TemporaryDirectory(prefix='readmd-doc-')` (:1190).  Hand-rolled
/// because the kernel has no `tempfile` dependency; the directory is removed on
/// `Drop`, including on the `return` that happens inside the `with` block.
pub struct TempDir {
    path: std::path::PathBuf,
}

impl TempDir {
    /// `mkdtemp`: create exclusively, retrying on collision.
    pub fn new(prefix: &str) -> std::io::Result<TempDir> {
        let base = std::env::temp_dir();
        let pid = std::process::id();
        for attempt in 0..128u32 {
            let nanos = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_nanos() as u64)
                .unwrap_or(0);
            let path = base.join(format!("{}{}-{}-{:x}", prefix, pid, nanos, attempt));
            match std::fs::create_dir(&path) {
                Ok(()) => return Ok(TempDir { path }),
                Err(ref e) if e.kind() == std::io::ErrorKind::AlreadyExists => continue,
                Err(e) => return Err(e),
            }
        }
        Err(std::io::Error::new(
            std::io::ErrorKind::AlreadyExists,
            "could not create a temporary directory",
        ))
    }
    pub fn path(&self) -> &Path {
        &self.path
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.path);
    }
}

/// `convert.doc2md(path, form_tables=True)`
pub fn doc2md(
    kernel: &dyn DocKernel,
    engines: &dyn DocEngines,
    path: &Path,
    form_tables: bool,
) -> DocMdResult {
    // ---- magic probe (:1180-1188), its own `except OSError` -------------------
    let size = match std::fs::metadata(path) {
        Ok(m) => m.len(),
        Err(e) => return DocMdResult::err(doc_read_failed(&e)),
    };
    if size > DOC_MAX_BYTES {
        return DocMdResult::err(DOC_ERR_TOO_LARGE);
    }
    let magic = match read_first8(path) {
        Ok(m) => m,
        Err(e) => return DocMdResult::err(doc_read_failed(&e)),
    };
    if magic != OLE2_MAGIC {
        return DocMdResult::err(DOC_ERR_NOT_OLE2);
    }

    // ---- engine ladder (:1189-1198) -------------------------------------------
    let mut last: Option<String> = None;
    match TempDir::new("readmd-doc-") {
        Ok(td) => {
            for i in 0..2 {
                let out = if i == 0 {
                    engines.doc2docx_word_com(path, td.path())
                } else {
                    engines.doc2docx_soffice(path, td.path())
                };
                let out = match out {
                    Ok(o) => o,
                    Err(e) => {
                        last = Some(e);
                        continue;
                    }
                };
                if let Some(p) = out {
                    if !p.is_empty() && is_file(&p) {
                        // `td` drops here, exactly as `with` would close it.
                        return engines.docx2md(Path::new(&p), form_tables, path);
                    }
                }
            }
        }
        // Python would let this escape `doc2md` uncaught; the kernel has no way to
        // raise, and both engines would fail on a missing scratch dir anyway, so
        // it is recorded the same way an engine failure is.
        Err(e) => last = Some(doc_read_failed(&e)),
    }

    // ---- 内置纯 Python 文本流与表格提取 (:1200-1203) --------------------------
    let pure_text = doc_extract_text_pure_python(kernel, path);
    if !pure_text.is_empty() && !py_strip(&pure_text).is_empty() {
        return DocMdResult::ok(format!("{}\n", py_strip(&pure_text)));
    }

    match last {
        Some(e) => DocMdResult::err(format!(
            "{}{}{}",
            DOC_ERR_CONVERT_FAILED_PREFIX, e, DOC_ERR_CONVERT_FAILED_SUFFIX
        )),
        None => DocMdResult::err(DOC_ERR_NO_ENGINE),
    }
}

fn is_file(p: &str) -> bool {
    std::fs::metadata(p).map(|m| m.is_file()).unwrap_or(false)
}

/// `f.read(8)` -- short files yield fewer than 8 bytes, which then compare
/// unequal to `OLE2_MAGIC` and produce `doc-not-ole2`.
fn read_first8(path: &Path) -> std::io::Result<[u8; 8]> {
    use std::io::Read;
    let mut f = std::fs::File::open(path)?;
    let mut buf = [0u8; 8];
    let mut got = 0usize;
    while got < 8 {
        match f.read(&mut buf[got..]) {
            Ok(0) => break,
            Ok(n) => got += n,
            Err(ref e) if e.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(e) => return Err(e),
        }
    }
    Ok(buf)
}

/// `'doc-read-failed：%s' % e` -- `str(OSError)`, which CPython renders as
/// `[Errno N] strerror: 'filename'`.  `io::Error`'s `Display` is close but not
/// identical; the difference is confined to this message.
fn doc_read_failed(e: &std::io::Error) -> String {
    format!("{}{}", DOC_ERR_READ_FAILED_PREFIX, e)
}

