    fn unhex(s: &str) -> Vec<u8> {
        (0..s.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap())
            .collect()
    }

    fn crafted(name: &str) -> Vec<u8> {
        let (_, hex, _) = CRAFTED
            .iter()
            .find(|(n, _, _)| *n == name)
            .unwrap_or_else(|| panic!("no crafted container named {}", name));
        unhex(hex)
    }

    fn crafted_expect(name: &str) -> String {
        CRAFTED
            .iter()
            .find(|(n, _, _)| *n == name)
            .map(|(_, _, e)| (*e).to_string())
            .unwrap_or_else(|| panic!("no crafted container named {}", name))
    }

