    /// The reason `DocStream` is an enum at all: the same characters reaching the
    /// parser as `bytes` can be thrown out by the printable-ratio gate that a
    /// `str` input walks straight past (convert.py:969-971).
    ///
    /// Both variants are fed *literally the same 200 code points*, which only
    /// works because the fixture is pure ASCII: CPython's `utf-8` rung (:955)
    /// succeeds on the first try, so no later rung can rescue the bytes path.
    /// The previous `b'\x81' * 196` junk proved nothing -- measured, CPython
    /// decodes it with `gb18030` into 102 printable ideographs (ratio 1.0, no
    /// gate at all), and it only looked gated because the test codec stub knows
    /// ASCII plus a curated oracle table and therefore falls through to latin1.
    ///
    /// The ungated side renders `## abcd`, not `abcd`: the :974-981 clean turns
    /// the 196 control chars into spaces, `strip()` leaves `abcd`, and
    /// `_classify_doc_heading` returns level 2 for any <=30-char line without a
    /// sentence terminator (convert.py:868).
    #[test]
    fn ratio_gate_applies_to_bytes_but_not_to_str() {
        let k = kernel();
        let junk = "\u{1}".repeat(196) + "abcd";
        assert_eq!(py_len(&junk), 200);
        // 4 printable / 200 code points = 0.02, far under 0.35 -> bytes dropped.
        assert_eq!(
            parse_doc_stream_to_md(&k, DocStream::Bytes(junk.as_bytes())),
            ""
        );
        // Identical text as a `str` only faces the `valid_chars < 4` gate.
        assert_eq!(
            parse_doc_stream_to_md(&k, DocStream::Text(&junk)),
            "## abcd",
            "str input must not be ratio-gated"
        );
    }

    #[test]
    fn py_strip_and_split_differ_from_rust_std() {
        // U+001C..U+001F are Python whitespace and are *not* Rust whitespace.
        assert_eq!(py_strip("\u{1c}\u{1d}\u{1e}\u{1f}x\u{1f}"), "x");
        assert_eq!("\u{1c}x\u{1c}".trim(), "\u{1c}x\u{1c}");
        assert_eq!(py_strip("\u{85}y\u{85}"), "y");
        assert_eq!(py_strip("\u{a0}\u{3000}z\u{2028}"), "z");
        // `split('\n')` must not break on the extra `splitlines()` boundaries.
        assert_eq!("a\u{2028}b".split('\n').count(), 1);
        assert_eq!("a\u{b}b".split('\n').count(), 1);
        assert_eq!("a\u{1c}b".split('\n').count(), 1);
        // ... while `str::lines()` would have dropped even the \n-only split.
        assert_eq!("a\nb\n".lines().count(), 2);
    }

    /// Both cells land in a `max_cols == 2` row, so `flush_table` appends the
    /// separator line built at convert.py:1006 after the header; the header alone
    /// is never the whole block (compare
    /// `stream_noise_prefix_does_not_flush_a_pending_table`).
    #[test]
    fn table_cells_escape_pipes_and_squash_only_space_and_tab() {
        let k = kernel();
        let got = parse_doc_stream_to_md(&k, DocStream::Text("a|b\u{7}c\td\u{7}"));
        assert_eq!(got, "| a\\|b | c d |\n| --- | --- |");
        // U+00A0 is *not* squashed by `[ \t]+` but *is* removed by `strip()`.
        let got2 = parse_doc_stream_to_md(&k, DocStream::Text("\u{a0}x\u{7}\u{a0}y\u{a0}\u{7}"));
        assert_eq!(got2, "| x | y |\n| --- | --- |");
    }

    /// Each line is `['one', '']` -> popped -> one cell, so `max_cols` is 1 and
    /// `flush_table` takes the `' '.join(r)` branch (:1011-1013) -- which is a
    /// no-op there, because a row can only reach it when it holds exactly one
    /// cell (a 2-cell row would force `max_cols >= 2`).  The two rows therefore
    /// become two blocks and the final join at :1054 separates them with a blank
    /// line.  Measured: CPython returns `'one\n\ntwo'`.
    #[test]
    fn single_column_table_rows_become_one_plain_block_per_row() {
        let k = kernel();
        let got = parse_doc_stream_to_md(&k, DocStream::Text("one\u{7}\ntwo\u{7}\n"));
        assert_eq!(got, "one\n\ntwo");
    }

    #[test]
    fn stream_noise_prefix_does_not_flush_a_pending_table() {
        let k = kernel();
        // `a\u{7}x` and `b\u{7}y` must land in ONE table even though a
        // `WordDocument` line sits between them (fidelity note 7).
        let src = "a\u{7}x\u{7}\nWordDocument junk\nb\u{7}y\u{7}\n";
        let got = parse_doc_stream_to_md(&k, DocStream::Text(src));
        assert_eq!(got, "| a | x |\n| --- | --- |\n| b | y |");
    }

