    #[test]
    fn trailing_empty_cell_is_popped_but_only_when_more_than_one_cell() {
        let k = kernel();
        // Four separators -> five empty cells -> one popped -> `any(cells)` false
        // at :1033 drops the row.  `\u{7}` alone cannot be used as the probe:
        // `len(text.strip()) < 4` (:962) returns '' long before the split, and
        // U+00A0-style whitespace is irrelevant because `\x07`.isspace() is False.
        assert_eq!(
            parse_doc_stream_to_md(&k, DocStream::Text("\u{7}\u{7}\u{7}\u{7}")),
            ""
        );
        // Two cells, last empty -> popped -> one cell -> max_cols 1 -> plain text.
        // `ab\u{7}` is only 3 stripped characters, so it dies at :962 -> '' too.
        assert_eq!(parse_doc_stream_to_md(&k, DocStream::Text("abcd\u{7}")), "abcd");
        assert_eq!(parse_doc_stream_to_md(&k, DocStream::Text("ab\u{7}")), "");
        // Exactly ONE pop happens, so a doubled separator still leaves a second
        // empty cell: `max_cols == 2` and the row renders as a padded table.
        assert_eq!(
            parse_doc_stream_to_md(&k, DocStream::Text("abcd\u{7}\u{7}")),
            "| abcd |  |\n| --- | --- |"
        );
    }

