    #[test]
    fn non_utf8_bytes_walk_the_decode_ladder() {
        let k = kernel();
        // 0x81/0x8D/0x8F/0x9D are undefined in cp1252 and the leading bytes are
        // invalid GB18030, so this falls all the way through to latin1.
        let raw: Vec<u8> = (0..512u32).map(|i| i as u8).collect();
        assert_eq!(
            parse_doc_stream_to_md(&k, DocStream::Bytes(&raw)),
            PARSE_BYTES_LADIN1
        );
        // A NUL blob is UTF-16LE by the sniff; its text is unprintable, so the
        // `valid_chars < 4` gate rejects it.
        assert_eq!(parse_doc_stream_to_md(&k, DocStream::Bytes(&[0u8; 64])), "");
        // 0xFF is invalid GB18030 but valid cp1252, so rung 3 wins.
        let gold = ANSI_CASES
            .iter()
            .find(|(h, _)| *h == "ff")
            .map(|(_, out)| *out)
            .unwrap();
        assert_eq!(decode_doc_ansi_bytes(&k, &[0xff]), gold);
    }

