    // ---- doc2md --------------------------------------------------------------

    struct MockEngines {
        com: String,
        soffice: String,
        _tag: &'static str,
    }

    impl MockEngines {
        fn new(com: &str, soffice: &str) -> MockEngines {
            MockEngines { com: com.to_string(), soffice: soffice.to_string(), _tag: "x" }
        }
        /// `soffice` names a file in this test's scratch directory.
        fn with_real_output(mut self, file: &Path) -> MockEngines {
            self.soffice = file.to_string_lossy().replace('\\', "/");
            self
        }
    }

    impl DocEngines for MockEngines {
        fn doc2docx_word_com(
            &self,
            _src: &Path,
            _out: &Path,
        ) -> Result<Option<ConvertedDocx>, String> {
            outcome(&self.com)
        }
        fn doc2docx_soffice(
            &self,
            _src: &Path,
            _out: &Path,
        ) -> Result<Option<ConvertedDocx>, String> {
            outcome(&self.soffice)
        }
        /// Returns an *error* tuple on purpose: `doc2md` must pass it through
        /// unchanged because convert.py:1198 never looks at the second element.
        fn docx2md(&self, _docx: &Path, form_tables: bool, _asset: &Path) -> DocMdResult {
            DocMdResult {
                text: format!("DOCX form_tables={}", form_tables),
                error: Some("docx-itself-failed".to_string()),
            }
        }
    }

    /// `raise:MSG` -> engine raised, `none` -> returned nothing, `ghost` ->
    /// returned a path that is not a file, anything else -> that path.
    fn outcome(spec: &str) -> Result<Option<ConvertedDocx>, String> {
        if let Some(msg) = spec.strip_prefix("raise:") {
            Err(msg.to_string())
        } else if spec == "none" {
            Ok(None)
        } else if spec == "ghost" {
            Ok(Some("Z:/definitely/not/here.docx".to_string()))
        } else {
            Ok(Some(spec.to_string()))
        }
    }

    fn scratch_dir() -> std::path::PathBuf {
        let dir = std::env::temp_dir().join("readmd-doc-legacy-tests");
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    fn write_scratch(name: &str, bytes: &[u8]) -> std::path::PathBuf {
        let p = scratch_dir().join(name);
        std::fs::write(&p, bytes).unwrap();
        p
    }

